CREATE TABLE dbo.office_customer_companies(company_id uniqueidentifier NOT NULL CONSTRAINT PK_office_customer_companies PRIMARY KEY,workspace_id uniqueidentifier NOT NULL CONSTRAINT UQ_office_customer_workspace UNIQUE);
CREATE TABLE dbo.office_customer_receipts(request_id uniqueidentifier NOT NULL CONSTRAINT PK_office_customer_receipts PRIMARY KEY,company_id uniqueidentifier NOT NULL,payload_hash char(64) NOT NULL,receipt_json nvarchar(max) NOT NULL CHECK(ISJSON(receipt_json)=1),created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
